mapper.select:
SELECT PRS_ID, PRS_NAME, PRS_COUNTRY, PRS_USE_YN, IFNULL(STAR_CATEGORY, 'GENERAL') AS STAR_CATEGORY, IFNULL(FOLLOWER_CNT, 0) AS FOLLOWER_CNT, (SELECT COUNT(*) FROM WH_AD_LOG WHERE PRS_ID = A.PRS_ID AND ACTION = 'IMPRESSION') AS AD_VIEW_CNT FROM WH_PRESS A WHERE PRS_TYPE = '4' AND PRS_AUTH = 'ST'
AND PRS_COUNTRY = #{country}
AND (PRS_NAME LIKE CONCAT('%', #{searchKeyword}, '%') OR PRS_ID LIKE CONCAT('%', #{searchKeyword}, '%'))
AND IFNULL(STAR_CATEGORY, 'GENERAL') = #{filterCategory}
ORDER BY (IFNULL(STAR_CATEGORY, 'GENERAL') = 'GENERAL') DESC, FOLLOWER_CNT DESC, PRS_CREATE_DATE DESC
LIMIT #{start}, #{length}

SELECT COUNT(*)
FROM WH_PRESS A
WHERE PRS_TYPE = '4' AND PRS_AUTH = 'ST'

    AND PRS_COUNTRY = #{country}


    AND (PRS_NAME LIKE CONCAT('%', #{searchKeyword}, '%') OR PRS_ID LIKE CONCAT('%', #{searchKeyword}, '%'))


    AND IFNULL(STAR_CATEGORY, 'GENERAL') = #{filterCategory}

mapper.update:
UPDATE WH_PRESS
SET STAR_CATEGORY = #{category},
    PRS_UPDATE_DATE = CURRENT_TIMESTAMP
WHERE PRS_ID = #{prsId}
  AND PRS_TYPE = '4' AND PRS_AUTH = 'ST'

  AND PRS_COUNTRY = #{country}

UPDATE WH_PRESS
SET PRS_BIO = #{bio},
    PRS_UPDATE_DATE = CURRENT_TIMESTAMP
WHERE PRS_ID = #{prsId}
  AND PRS_TYPE = '4' AND PRS_AUTH = 'ST'

  AND PRS_COUNTRY = #{country}

mapper.select:
SELECT * FROM ( SELECT 'MEMBER_CONTENT' AS TARGET_TYPE, CAST(C.CON_ID AS CHAR) AS TARGET_ID, C.CON_TITLE AS TITLE, C.CON_BODY AS BODY, C.CON_THUMNAIL AS IMAGE_URL, IF(C.CON_ORIGIN_URL LIKE '%.mp4', C.CON_ORIGIN_URL, NULL) AS VIDEO_URL, C.MDR_STATUS, DATE_FORMAT(C.CON_CREATE_DATE, '%Y-%m-%d %H:%i') AS CREATED_TEXT, C.CON_CREATE_DATE AS CREATED_DATE, IFNULL(P.PRS_NAME, C.PRS_ID) AS WRITER FROM WH_CONTENT C LEFT JOIN WH_PRESS P ON C.PRS_ID = P.PRS_ID WHERE C.MDR_STATUS = #{status}
UNION ALL
SELECT 'STAR_FEED' AS TARGET_TYPE, CAST(S.CON_ID AS CHAR) AS TARGET_ID, NULL AS TITLE, S.CON_BODY AS BODY, IFNULL( (SELECT D.MEDIA_URL FROM STAR_CONTENT_MEDIA D WHERE D.CON_ID = S.CON_ID AND D.MEDIA_TYPE = 'PHOTO' ORDER BY D.SORT_ORDER LIMIT 1), (SELECT D.THUMB_URL FROM STAR_CONTENT_MEDIA D WHERE D.CON_ID = S.CON_ID AND D.MEDIA_TYPE = 'VIDEO' ORDER BY D.SORT_ORDER LIMIT 1) ) AS IMAGE_URL, (SELECT D.MEDIA_URL FROM STAR_CONTENT_MEDIA D WHERE D.CON_ID = S.CON_ID AND D.MEDIA_TYPE = 'VIDEO' ORDER BY D.SORT_ORDER LIMIT 1) AS VIDEO_URL, S.MDR_STATUS, DATE_FORMAT(S.CREATED_DATE, '%Y-%m-%d %H:%i') AS CREATED_TEXT, S.CREATED_DATE, IFNULL(P.PRS_NAME, S.PRS_ID) AS WRITER FROM WH_STAR_CONTENT S LEFT JOIN WH_PRESS P ON S.PRS_ID = P.PRS_ID WHERE S.MDR_STATUS = #{status} ) Q ORDER BY Q.CREATED_DATE ASC LIMIT 200

