mapper.select:
SELECT P.PRS_ID, P.PRS_NAME, P.STORED_FILE_NM, P.PRS_COUNTRY, IFNULL(S.TOTAL, 0) AS TOTAL FROM WH_PRESS P LEFT JOIN ( SELECT PRS_ID, AS TOTAL FROM WH_STAR_DAILY_STAT WHERE STAT_DATE >= #{fromDate} AND STAT_DATE < #{toDate} GROUP BY PRS_ID ) S ON S.PRS_ID = P.PRS_ID WHERE P.PRS_USE_YN = 'Y' AND P.IS_STAR = 'Y'
AND P.PRS_COUNTRY = #{country}
ORDER BY TOTAL DESC, P.PRS_ID ASC LIMIT #{start}, #{length}

SELECT COUNT(*) FROM WH_PRESS P
WHERE P.PRS_USE_YN = 'Y' AND P.IS_STAR = 'Y'

  AND P.PRS_COUNTRY = #{country}
